-- DCI 2026 : mise a jour des codes des DCI deja presentes.
--
-- Pour chaque DCI du fichier DCI2026.csv, la DCI deja en base sous le MEME NOM (sans tenir compte des majuscules,
-- des accents ni des espaces) prend le nouveau code. Son identifiant ne change pas : les produits qui lui sont
-- rattaches (t_famille_dci) restent lies. Le libelle n'est pas modifie.
--
-- ORDRE CONSEILLE
--   1. ce script (les DCI existantes prennent leur code 2026) ;
--   2. dci_2026_sans_doublons.sql (ajoute les DCI qui n'existaient pas).
--   Resultat : les 1274 codes 2026 presents, aucune DCI en double.
--   NE PAS lancer dci_2026.sql avant ce script : il creerait les nouveaux codes sur de nouvelles lignes, et les
--   DCI existantes ne pourraient plus les prendre (code unique).
--
-- Quand plusieurs DCI portent deja le meme nom, une seule prend le nouveau code : la DCI active, puis la plus
-- ancienne. Les autres gardent leur ancien code.
-- Rejouable sans effet. Fichier en UTF-8 : dans HeidiSQL, l'ouvrir avec l'encodage UTF-8.

SET NAMES utf8;

-- 0. Sauvegarde des codes actuels (une seule fois : un second passage ne l'ecrase pas).
CREATE TABLE IF NOT EXISTS t_dci_sauvegarde_2026 AS SELECT * FROM t_dci;

-- 1. Mise a jour des codes.

UPDATE IGNORE `t_dci` SET `str_CODE` = 'A081', `dt_UPDATED` = NOW() WHERE REPLACE(`str_NAME`, ' ', '') = REPLACE('ABIRATERONE', ' ', '') AND `str_CODE` <> 'A081' ORDER BY (`str_STATUT` = 'enable') DESC, `dt_CREATED`, `lg_DCI_ID` LIMIT 1;
