-- 2. Verification : DCI qui ont change de code (ancien code -> nouveau code).
SELECT s.str_CODE AS ancien_code, d.str_CODE AS nouveau_code, d.str_NAME, d.str_STATUT
FROM t_dci d JOIN t_dci_sauvegarde_2026 s ON s.lg_DCI_ID = d.lg_DCI_ID
WHERE s.str_CODE <> d.str_CODE
ORDER BY d.str_NAME;

